<section aria-labelledby="browser-game-combat-heading"><h2 id="browser-game-combat-heading">Combat</h2>@if($message)<p role="status">{{ $message }}</p>@endif @forelse ($battles as $battle)<article wire:key="battle-{{ $battle->id }}"><h3>{{ $battle->actor_id }} vs {{ $battle->opponent_id }}</h3><p>{{ $battle->status }} · turn {{ $battle->turn }}</p>@if($battle->status === 'active')<button type="button" wire:click="attack('{{ $battle->id }}')" wire:loading.attr="disabled">Attack</button> <button type="button" wire:click="resolveAction('{{ $battle->id }}', 'defend', 0)" wire:loading.attr="disabled">Defend</button> <button type="button" wire:click="resolveAction('{{ $battle->id }}', 'heal', 10)" wire:loading.attr="disabled">Heal</button>@endif @if(!empty($battle->state['log']))<details><summary>Combat log</summary><ol>@foreach($battle->state['log'] as $entry)<li>{{ $entry['action'] }}: {{ $entry['value'] }}</li>@endforeach</ol></details>@endif</article>@empty<p role="status">No combat is available.</p>@endforelse <form wire:submit="simulate('{{ $simulationOpponentId }}')"><label>Simulation opponent <input wire:model="simulationOpponentId" required></label><button type="submit">Simulate</button></form>@if($simulation !== [])<pre aria-label="Combat simulation">{{ json_encode($simulation, JSON_PRETTY_PRINT) }}</pre>@endif</section>
